draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  // draw a fruit
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  // draw a character
  ctx.beginPath();
  ctx.arc(W/2 + 100 + 20 * Math.cos(t), H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 + 20 * Math.cos(t), H/2 + 20);
  ctx.lineTo(W/2 + 100 + 20 * Math.cos(t), H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 + 20 * Math.cos(t), H/2 + 30);
  ctx.lineTo(W/2 + 80 + 20 * Math.cos(t), H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 + 20 * Math.cos(t), H/2 + 30);
  ctx.lineTo(W/2 + 120 + 20 * Math.cos(t), H/2 + 50);
  ctx.stroke();
  // draw a speech bubble
  ctx.beginPath();
  ctx.arc(W/2 + 150 + 10 * Math.sin(t), H/2 - 50, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Eat healthy!', W/2 + 150 + 10 * Math.sin(t), H/2 - 50);
  ctx.restore();
}
